source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A horizontal 5-bar carries the vertical color sequence below it across the bar.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c + 1 < w and grid[r][c + 1] == 5:
                c += 1
            end = c
            if end > start and r + 1 < h:
                anchor = next((x for x in range(start, end + 1) if grid[r + 1][x] not in (0, 5)), None)
                if anchor is not None:
                    rr = r + 1
                    while rr < h and grid[rr][anchor] not in (0, 5):
                        value = grid[rr][anchor]
                        for x in range(start, end + 1):
                            if grid[rr][x] == 0:
                                out[rr][x] = value
                        rr += 1
            c += 1

    # A vertical 5-bar carries the adjacent horizontal color block along its length.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r + 1 < h and grid[r + 1][c] == 5:
                r += 1
            end = r
            if end > start and c + 1 < w:
                # The source block is the contiguous set of colored rows ending at the bar's lower end.
                src_end = end
                if grid[src_end][c + 1] not in (0, 5):
                    src_start = src_end
                    while src_start > start and grid[src_start - 1][c + 1] not in (0, 5):
                        src_start -= 1
                    pattern = []
                    for rr in range(src_start, src_end + 1):
                        row_pattern = []
                        x = c + 1
                        while x < w and grid[rr][x] not in (0, 5):
                            row_pattern.append(grid[rr][x])
                            x += 1
                        pattern.append(row_pattern)
                    if pattern and all(pattern):
                        for rr in range(start, end + 1):
                            row_pattern = pattern[(rr - src_start) % len(pattern)]
                            for k, value in enumerate(row_pattern, start=c + 1):
                                if k < w and grid[rr][k] == 0:
                                    out[rr][k] = value
            r += 1
    return out
